/*
  Controle do telescopio - Prof. Joao Paulo
  ESP32 + TB6600 + AccelStepper + OTA pelo navegador.

  IMPORTANTE:
  - Wi-Fi: Canhao_Red / profjoaopaulo.
  - GPIOs mantidos conforme este projeto: STEP=25 e DIR=26; confirme antes de gravar.
  - Driver configurado para PUL+ e DIR+ em +5V (como descrito no projeto);
    PUL- recebe STEP e DIR- recebe DIR. Confira compatibilidade eletrica.
  - A primeira gravacao desta versao ainda precisa ser feita pelo Arduino IDE.
  - Depois, a atualizacao pode ser feita no navegador pelo Wi-Fi da ESP32.
*/

#include <WiFi.h>
#include <WebServer.h>
#include <Update.h>
#include <AccelStepper.h>

// >>> PREENCHA com o MESMO nome e senha do Wi-Fi da ESP32 que voce ja usa <<<
const char* AP_SSID = "Canhao_Red";
const char* AP_PASSWORD = "profjoaopaulo";

// Mantenha os pinos do projeto atual. Valores de referencia do projeto: 25 e 26.
static const int STEP_PIN = 25;
static const int DIR_PIN  = 26;

WebServer server(80);
AccelStepper motor(AccelStepper::DRIVER, STEP_PIN, DIR_PIN);

volatile bool moving = false;
volatile bool tracking = false;
volatile bool reversed = false;
volatile int moveDir = 1;
float jogSpeed = 20.0f;       // passos por segundo
float trackingSpeed = 0.4f;   // passos por segundo
float targetSpeed = 0.0f;
float currentSpeed = 0.0f;
static const float ACCELERATION = 80.0f; // passos/s²: rampa suave de aceleração e frenagem
uint32_t lastRampMicros = 0;

const char INDEX_HTML[] PROGMEM = R"HTMLPAGE(
<!doctype html><html lang="pt-BR"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Canhão Red — Prof. João Paulo</title>
<style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#101827;color:#f4f7fb;font-family:Arial,sans-serif}
header{padding:18px 14px;text-align:center;background:#17243a;border-bottom:1px solid #30415c}
h1{font-size:1.25rem;margin:0 0 5px}header p{margin:0;color:#b9c9df;font-size:.9rem}
main{max-width:680px;margin:auto;padding:14px;display:grid;gap:13px}.card{background:#19263b;border:1px solid #30415c;border-radius:14px;padding:15px}
h2{font-size:1.05rem;margin:0 0 12px}.row{display:flex;gap:9px;flex-wrap:wrap}.row>*{flex:1}
button{border:0;border-radius:10px;padding:14px 10px;font-weight:bold;font-size:1rem;color:#fff;background:#2868bd;min-height:48px}
button.stop{background:#b93442}button.alt{background:#43546e}button:active{filter:brightness(1.25)}
label{display:block;color:#c5d2e4;margin:12px 0 6px;font-size:.92rem}
input{width:100%;padding:12px;border-radius:8px;border:1px solid #50627d;background:#0d1522;color:white;font-size:1rem}
.small{font-size:.85rem;color:#b9c9df;line-height:1.4}.status{padding:10px;border-radius:8px;background:#0d1522;color:#aee5c0;margin-top:9px;overflow-wrap:anywhere}
button.hold{touch-action:none;background:#237e70;min-height:76px;font-size:2rem}button.icon{font-size:2rem;min-height:64px}button:focus{outline:2px solid #a9c9ff;outline-offset:2px}.hint{color:#ffd78a}
</style></head><body>
<header><h1>Canhão Red</h1><p>Prof. João Paulo · Controle Wi-Fi do telescópio</p></header>
<main>
<section class="card"><h2>Movimento manual</h2>
<div class="row"><button class="hold icon" id="holdUp" aria-label="Subir" title="Subir">▲</button><button class="hold icon" id="holdDown" aria-label="Descer" title="Descer">▼</button><button class="stop icon" onclick="stopAll()" aria-label="Parar" title="Parar">■</button></div>
<label>Velocidade manual (0,01 a 200 passos/s)</label>
<input id="jog" type="number" min="0.01" max="200" step="0.01" value="20">
<p class="small">Toque e mantenha ▲ ou ▼ pressionado. Ao soltar, o motor desacelera e para suavemente.</p>
</section>
<section class="card"><h2>Acompanhamento</h2>
<label>Velocidade de acompanhamento (0,001 a 50 passos/s)</label>
<input id="track" type="number" min="0.001" max="50" step="0.001" value="0.4">
<div class="row" style="margin-top:10px"><button onclick="startTrack()">▶ Iniciar acompanhamento</button><button class="stop" onclick="stopAll()">■ Parar</button></div>
<p class="small">O sentido do acompanhamento respeita a opção de reversão abaixo.</p>
</section>
<section class="card"><h2>Sentido do motor</h2>
<div class="row"><button class="alt" onclick="reverseAll()">⇄ REVERTER TUDO</button></div>
<p class="small">Inverte SUBIR/DESCER e o sentido do acompanhamento, sem trocar fios.</p>
</section>
<section class="card"><h2>Atualização OTA</h2>
<p class="small">Selecione o arquivo de firmware <b>.bin</b> compilado para esta ESP32. Não desligue a placa durante a atualização.</p>
<input id="firmware" type="file" accept=".bin,application/octet-stream">
<div class="row" style="margin-top:10px"><button onclick="uploadFirmware()">Atualizar firmware (.bin)</button></div>
<p class="small hint">A atualização reinicia a placa ao terminar. Use somente um .bin compilado para esta placa.</p>
</section>
<div id="status" class="status">Conecte-se ao Wi-Fi da ESP32 e abra esta página.</div>
</main>
<script>
const $=id=>document.getElementById(id);
async function api(path){try{let r=await fetch(path);let t=await r.text();$('status').textContent=t;if(!r.ok)throw Error(t);return t}catch(e){$('status').textContent='Falha de comunicação: '+e;}}
function val(id){return $(id).value.replace(',','.');}
async function stopAll(){await api('/stop');}
async function startTrack(){await api('/track?speed='+encodeURIComponent(val('track')));}
async function reverseAll(){await api('/reverse');}
async function holdStart(d){await api('/hold?dir='+d+'&speed='+encodeURIComponent(val('jog')));}
async function holdStop(){await api('/stop');}
for(const [id,d] of [['holdUp',1],['holdDown',-1]]){
 const b=$(id);
 b.addEventListener('contextmenu',e=>e.preventDefault());
 b.addEventListener('pointerdown',e=>{e.preventDefault();try{b.setPointerCapture(e.pointerId)}catch(_){}holdStart(d)});
 b.addEventListener('pointerup',e=>{e.preventDefault();holdStop()});
 b.addEventListener('pointercancel',holdStop);
 b.addEventListener('lostpointercapture',holdStop);
}
async function uploadFirmware(){
 const f=$('firmware').files[0]; if(!f){$('status').textContent='Escolha primeiro um arquivo .bin.';return;}
 if(!f.name.toLowerCase().endsWith('.bin')){$('status').textContent='O arquivo precisa terminar em .bin.';return;}
 if(!confirm('Atualizar o firmware agora? A placa reiniciará ao terminar.'))return;
 const fd=new FormData();fd.append('firmware',f);
 $('status').textContent='Enviando firmware... não desligue a placa.';
 try{const r=await fetch('/update',{method:'POST',body:fd});const t=await r.text();$('status').textContent=t+' A placa pode reiniciar em alguns segundos.';}
 catch(e){$('status').textContent='Conexão encerrada durante a atualização. Aguarde a reinicialização e reconecte ao Wi-Fi.';}
}
</script></body></html>
)HTMLPAGE";

void sendStatus(const String &s, int code = 200) {
  server.send(code, "text/plain; charset=utf-8", s);
}

bool readSpeedArg(const char* argName, float minV, float maxV, float &out) {
  if (!server.hasArg(argName)) return false;
  out = server.arg(argName).toFloat();
  return isfinite(out) && out >= minV && out <= maxV;
}

void stopMotor() {
  // Solicita uma parada suave: o loop continua gerando pulsos durante a desaceleracao.
  tracking = false;
  targetSpeed = 0.0f;
}

void setMovement(int dir, float speed, bool holdMode) {
  stopMotor();
  jogSpeed = speed;
  moveDir = (dir >= 0 ? 1 : -1);
  if (reversed) moveDir *= -1;
  tracking = false;
  moving = true;
  targetSpeed = moveDir * jogSpeed;
  sendStatus(holdMode ? "Movimento ativo; ao soltar, desacelera e para." :
             "Movimento iniciado com aceleracao suave.");
}

void setup() {
  Serial.begin(115200);
  motor.setMaxSpeed(2000.0);
  motor.setMinPulseWidth(3);
  motor.setSpeed(0);

  WiFi.mode(WIFI_AP);
  bool apOK = WiFi.softAP(AP_SSID, AP_PASSWORD);
  Serial.println(apOK ? "Wi-Fi AP iniciado" : "Falha ao iniciar Wi-Fi AP");
  Serial.print("SSID: "); Serial.println(AP_SSID);
  Serial.print("IP: "); Serial.println(WiFi.softAPIP());

  server.on("/", HTTP_GET, [](){ server.send_P(200, "text/html; charset=utf-8", INDEX_HTML); });
  server.on("/move", HTTP_GET, [](){
    int d = server.arg("dir").toInt();
    float s;
    if ((d != 1 && d != -1) || !readSpeedArg("speed", 0.01f, 200.0f, s)) {
      sendStatus("Valor inválido. Velocidade: 0,01 a 200 passos/s.", 400); return;
    }
    setMovement(d, s, false);
  });
  server.on("/hold", HTTP_GET, [](){
    int d = server.arg("dir").toInt();
    float s;
    if ((d != 1 && d != -1) || !readSpeedArg("speed", 0.01f, 200.0f, s)) {
      sendStatus("Valor inválido. Velocidade: 0,01 a 200 passos/s.", 400); return;
    }
    setMovement(d, s, true);
  });
  server.on("/stop", HTTP_GET, [](){ stopMotor(); sendStatus("Motor parado."); });
  server.on("/track", HTTP_GET, [](){
    float s;
    if (!readSpeedArg("speed", 0.001f, 50.0f, s)) {
      sendStatus("Valor inválido. Acompanhamento: 0,001 a 50 passos/s.", 400); return;
    }
    stopMotor();
    trackingSpeed = s;
    moveDir = reversed ? -1 : 1;
    tracking = true;
    moving = true;
    targetSpeed = moveDir * trackingSpeed;
    sendStatus("Acompanhamento continuo iniciado em " + String(trackingSpeed, 3) + " passos/s.");
  });
  server.on("/reverse", HTTP_GET, [](){
    reversed = !reversed;
    if (moving) {
      moveDir *= -1;
      targetSpeed = moveDir * (tracking ? trackingSpeed : jogSpeed);
    }
    sendStatus(String("Reversão ") + (reversed ? "ATIVADA." : "desativada."));
  });
  server.on("/update", HTTP_POST,
    []() {
      bool ok = !Update.hasError();
      server.send(200, "text/plain; charset=utf-8", ok ? "Atualização concluída." : "Falha na atualização.");
      delay(250);
      if (ok) ESP.restart();
    },
    []() {
      HTTPUpload& upload = server.upload();
      if (upload.status == UPLOAD_FILE_START) {
        stopMotor();
        if (!upload.filename.endsWith(".bin")) Update.abort();
        else if (!Update.begin(UPDATE_SIZE_UNKNOWN)) Update.printError(Serial);
      } else if (upload.status == UPLOAD_FILE_WRITE) {
        if (Update.write(upload.buf, upload.currentSize) != upload.currentSize) Update.printError(Serial);
      } else if (upload.status == UPLOAD_FILE_END) {
        if (!Update.end(true)) Update.printError(Serial);
      }
    }
  );
  server.begin();
}

void loop() {
  server.handleClient();

  // Rampa de velocidade nao bloqueante; permite atender Wi-Fi e OTA durante o movimento.
  uint32_t now = micros();
  if (lastRampMicros == 0) lastRampMicros = now;
  float dt = (uint32_t)(now - lastRampMicros) / 1000000.0f;
  lastRampMicros = now;
  if (dt > 0.05f) dt = 0.05f; // evita saltos grandes apos uma operacao demorada

  float difference = targetSpeed - currentSpeed;
  float maxChange = ACCELERATION * dt;
  if (difference > maxChange) difference = maxChange;
  else if (difference < -maxChange) difference = -maxChange;
  currentSpeed += difference;

  if (fabsf(currentSpeed) > 0.001f) {
    motor.setSpeed(currentSpeed);
    motor.runSpeed();
  } else {
    currentSpeed = 0.0f;
    motor.setSpeed(0);
    if (targetSpeed == 0.0f) moving = false;
  }
  delay(0);
}
